def compare_backspaced_streams(stream_s, stream_t):
    p_s, p_t = len(stream_s) - 1, len(stream_t) - 1
    skip_s, skip_t = 0, 0
    while p_s >= 0 or p_t >= 0:
        while p_s >= 0:
            if stream_s[p_s] == "#":
                skip_s += 1
                p_s -= 1
            elif skip_s > 0:
                skip_s -= 1
                p_s -= 1
            else:
                break
        while p_t >= 0:
            if stream_t[p_t] == "#":
                skip_t += 1
                p_t -= 1
            elif skip_t > 0:
                skip_t -= 1
                p_t -= 1
            else:
                break
        if p_s >= 0 and p_t >= 0 and stream_s[p_s] != stream_t[p_t]:
            return False
        if (p_s >= 0) != (p_t >= 0):
            return False
        p_s -= 1
        p_t -= 1
    return True

