def find_anagram_start_indices(search_text, pattern_str):
    if len(search_text) < len(pattern_str):
        return []
    pat_counts = {}
    for ch in pattern_str:
        pat_counts[ch] = pat_counts.get(ch, 0) + 1
    win_counts = {}
    k = len(pattern_str)
    for ch in search_text[:k]:
        win_counts[ch] = win_counts.get(ch, 0) + 1
    results = []
    if win_counts == pat_counts:
        results.append(0)
    for i in range(k, len(search_text)):
        incoming = search_text[i]
        outgoing = search_text[i - k]
        win_counts[incoming] = win_counts.get(incoming, 0) + 1
        win_counts[outgoing] -= 1
        if win_counts[outgoing] == 0:
            del win_counts[outgoing]
        if win_counts == pat_counts:
            results.append(i - k + 1)
    return results

