def min_window_substring_cover(source_log, query_chars):
    if not source_log or not query_chars:
        return ""
    target_counts = {}
    for c in query_chars:
        target_counts[c] = target_counts.get(c, 0) + 1
    required = len(target_counts)
    window_counts = {}
    formed = 0
    left = 0
    ans = (float("inf"), 0, 0)
    for right in range(len(source_log)):
        c = source_log[right]
        window_counts[c] = window_counts.get(c, 0) + 1
        if c in target_counts and window_counts[c] == target_counts[c]:
            formed += 1
        while left <= right and formed == required:
            if (right - left + 1) < ans[0]:
                ans = (right - left + 1, left, right)
            evicted = source_log[left]
            window_counts[evicted] -= 1
            if evicted in target_counts and window_counts[evicted] < target_counts[evicted]:
                formed -= 1
            left += 1
    return source_log[ans[1]:ans[2] + 1] if ans[0] != float("inf") else ""

def count_subarrays_with_exact_k_distinct(data_stream, distinct_k):
    def at_most_distinct(k):
        counts = {}
        left = 0
        res = 0
        for right in range(len(data_stream)):
            val = data_stream[right]
            if counts.get(val, 0) == 0:
                k -= 1
            counts[val] = counts.get(val, 0) + 1
            while k < 0:
                counts[data_stream[left]] -= 1
                if counts[data_stream[left]] == 0:
                    k += 1
                left += 1
            res += (right - left + 1)
        return res
    return at_most_distinct(distinct_k) - at_most_distinct(distinct_k - 1)

