def max_vowels_in_window(text_stream, window_len):
    vowels = set("aeiou")
    curr_vowels = sum(1 for ch in text_stream[:window_len] if ch in vowels)
    max_vowels = curr_vowels
    for i in range(window_len, len(text_stream)):
        if text_stream[i] in vowels:
            curr_vowels += 1
        if text_stream[i - window_len] in vowels:
            curr_vowels -= 1
        if curr_vowels > max_vowels:
            max_vowels = curr_vowels
    return max_vowels

def max_turbulent_subarray_len(readings):
    n = len(readings)
    if n < 2:
        return n
    left = 0
    max_len = 1
    for right in range(1, n):
        c = (readings[right] > readings[right - 1]) - (readings[right] < readings[right - 1])
        if c == 0:
            left = right
        elif right == n - 1 or c * ((readings[right + 1] > readings[right]) - (readings[right + 1] < readings[right])) != -1:
            max_len = max(max_len, right - left + 1)
            left = right
    return max_len

def max_satisfied_customers(customers, grumpy, minutes):
    base_satisfied = sum(c for c, g in zip(customers, grumpy) if g == 0)
    bonus = sum(customers[i] for i in range(minutes) if grumpy[i] == 1)
    max_bonus = bonus
    for i in range(minutes, len(customers)):
        if grumpy[i] == 1:
            bonus += customers[i]
        if grumpy[i - minutes] == 1:
            bonus -= customers[i - minutes]
        if bonus > max_bonus:
            max_bonus = bonus
    return base_satisfied + max_bonus

def num_subarray_bounded_max(nums, left_bound, right_bound):
    def count_at_most(bound):
        ans = 0
        curr = 0
        for x in nums:
            if x <= bound:
                curr += 1
            else:
                curr = 0
            ans += curr
        return ans
    return count_at_most(right_bound) - count_at_most(left_bound - 1)

