def longest_subarray_within_diff_limit(data_points, limit_delta):
    min_deque = deque()
    max_deque = deque()
    left = 0
    max_len = 0
    for right in range(len(data_points)):
        val = data_points[right]
        while min_deque and data_points[min_deque[-1]] > val:
            min_deque.pop()
        min_deque.append(right)
        while max_deque and data_points[max_deque[-1]] < val:
            max_deque.pop()
        max_deque.append(right)
        while data_points[max_deque[0]] - data_points[min_deque[0]] > limit_delta:
            left += 1
            if min_deque[0] < left:
                min_deque.popleft()
            if max_deque[0] < left:
                max_deque.popleft()
        max_len = max(max_len, right - left + 1)
    return max_len

def find_complement_index_pair(sensor_metrics, target_balance):
    seen_indices = {}
    for index, value in enumerate(sensor_metrics):
        complement = target_balance - value
        if complement in seen_indices:
            return [seen_indices[complement], index]
        seen_indices[value] = index
    return []

