def count_subarrays_with_sum(data_stream, target_sum):
    prefix_counts = {0: 1}
    current_sum = 0
    total_subarrays = 0
    for val in data_stream:
        current_sum += val
        needed_prefix = current_sum - target_sum
        if needed_prefix in prefix_counts:
            total_subarrays += prefix_counts[needed_prefix]
        prefix_counts[current_sum] = prefix_counts.get(current_sum, 0) + 1
    return total_subarrays

def longest_consecutive_chain(sequence_ids):
    id_set = set(sequence_ids)
    longest_streak = 0
    for num in id_set:
        if num - 1 not in id_set:
            current_num = num
            current_streak = 1
            while current_num + 1 in id_set:
                current_num += 1
                current_streak += 1
            if current_streak > longest_streak:
                longest_streak = current_streak
    return longest_streak

def top_k_frequent_telemetry(data_readings, top_k):
    counts = {}
    for num in data_readings:
        counts[num] = counts.get(num, 0) + 1
    buckets = [[] for _ in range(len(data_readings) + 1)]
    for num, freq in counts.items():
        buckets[freq].append(num)
    result = []
    for freq in range(len(buckets) - 1, 0, -1):
        for num in buckets[freq]:
            result.append(num)
            if len(result) == top_k:
                return result
    return result

def find_longest_zero_sum_span(transactions):
    prefix_indices = {0: -1}
    current_sum = 0
    max_length = 0
    for i, val in enumerate(transactions):
        current_sum += val
        if current_sum in prefix_indices:
            max_length = max(max_length, i - prefix_indices[current_sum])
        else:
            prefix_indices[current_sum] = i
    return max_length

def has_close_duplicate_timestamps(event_ids, max_gap):
    last_seen = {}
    for i, event_id in enumerate(event_ids):
        if event_id in last_seen and i - last_seen[event_id] <= max_gap:
            return True
        last_seen[event_id] = i
    return False

def is_isomorphic_mapping(stream_s, stream_t):
    map_s_to_t = {}
    map_t_to_s = {}
    for c1, c2 in zip(stream_s, stream_t):
        if (c1 in map_s_to_t and map_s_to_t[c1] != c2) or (c2 in map_t_to_s and map_t_to_s[c2] != c1):
            return False
        map_s_to_t[c1] = c2
        map_t_to_s[c2] = c1
