def word_pattern_matches(pattern_chars, words_text):
    words = words_text.split()
    if len(pattern_chars) != len(words):
        return False
    char_to_word = {}
    word_to_char = {}
    for c, w in zip(pattern_chars, words):
        if (c in char_to_word and char_to_word[c] != w) or (w in word_to_char and word_to_char[w] != c):
            return False
        char_to_word[c] = w
        word_to_char[w] = c
    return True

def has_subarray_divisible_by_k(nums, modulo_k):
    remainder_indices = {0: -1}
    curr_sum = 0
    for i, num in enumerate(nums):
        curr_sum += num
        rem = curr_sum % modulo_k
        if rem in remainder_indices:
            if i - remainder_indices[rem] >= 2:
                return True
        else:
            remainder_indices[rem] = i
    return False

def find_max_length_equal_01(binary_tape):
    prefix_indices = {0: -1}
    count = 0
    max_len = 0
    for i, val in enumerate(binary_tape):
        count += (1 if val == 1 else -1)
        if count in prefix_indices:
            max_len = max(max_len, i - prefix_indices[count])
        else:
            prefix_indices[count] = i
    return max_len

