def find_lhs_length(metrics):
    counts = Counter(metrics)
    max_len = 0
    for x in counts:
        if x + 1 in counts:
            max_len = max(max_len, counts[x] + counts[x + 1])
    return max_len

from collections import Counter

def intersect_frequency_arrays(nums1, nums2):
    counts1 = Counter(nums1)
    intersection = []
    for x in nums2:
        if counts1.get(x, 0) > 0:
            intersection.append(x)
            counts1[x] -= 1
    return intersection

from collections import defaultdict

def least_bricks_crossed(wall_rows):
    edge_counts = defaultdict(int)
    for row in wall_rows:
        pos = 0
        for brick in row[:-1]:
            pos += brick
            edge_counts[pos] += 1
    max_edges = max(edge_counts.values()) if edge_counts else 0
    return len(wall_rows) - max_edges

