def subarrays_div_by_k_count(nums, divisor_k):
    rem_counts = {0: 1}
    prefix_sum = 0
    total_count = 0
    for x in nums:
        prefix_sum += x
        rem = prefix_sum % divisor_k
        if rem in rem_counts:
            total_count += rem_counts[rem]
        rem_counts[rem] = rem_counts.get(rem, 0) + 1
    return total_count

