def can_pair_divisible_by_k(arr, k):
    remainders = Counter(x % k for x in arr)
    for rem in remainders:
        if rem == 0:
            if remainders[rem] % 2 != 0:
                return False
        elif 2 * rem == k:
            if remainders[rem] % 2 != 0:
                return False
        else:
            if remainders[rem] != remainders.get(k - rem, 0):
                return False
    return True

def find_missing_and_repeated_values(grid_matrix):
    n = len(grid_matrix)
    total_nums = n * n
    counts = {}
    for row in grid_matrix:
        for val in row:
            counts[val] = counts.get(val, 0) + 1
    repeated = -1
    missing = -1
    for x in range(1, total_nums + 1):
        c = counts.get(x, 0)
        if c == 2:
            repeated = x
        elif c == 0:
            missing = x
    return [repeated, missing]

def minimum_incompatibility_sum(task_ids, group_count):
    n = len(task_ids)
    k = group_count
    subset_size = n // k
    task_ids.sort()
    memo = {}
    def dp(mask):
        if mask == (1 << n) - 1:
            return 0
        if mask in memo:
            return memo[mask]
        count = bin(mask).count("1")
        first_unpicked = 0
        while (mask >> first_unpicked) & 1:
            first_unpicked += 1
        ans = float("inf")
        def pick_group(idx, group_mask, last_val, gathered):
            nonlocal ans
            if gathered == subset_size:
                elements = [task_ids[i] for i in range(n) if (group_mask >> i) & 1]
                incompat = max(elements) - min(elements)
                ans = min(ans, incompat + dp(mask | group_mask))
                return
            for i in range(idx, n):
                if not ((mask >> i) & 1) and not ((group_mask >> i) & 1):
                    if task_ids[i] != last_val:
                        pick_group(i + 1, group_mask | (1 << i), task_ids[i], gathered + 1)
        pick_group(first_unpicked, 0, -1, 0)
        memo[mask] = ans
        return ans
    res = dp(0)
    return res if res != float("inf") else -1

def count_distinct_climbing_ways(total_steps):
    if total_steps <= 2:
        return total_steps
    prev2, prev1 = 1, 2
    for _ in range(3, total_steps + 1):
        curr = prev1 + prev2
        prev2 = prev1
        prev1 = curr
    return prev1

def max_non_adjacent_energy_yield(node_capacities):
    if not node_capacities:
        return 0
    if len(node_capacities) <= 2:
        return max(node_capacities)
    prev2 = node_capacities[0]
    prev1 = max(node_capacities[0], node_capacities[1])
    for i in range(2, len(node_capacities)):
        curr = max(prev1, prev2 + node_capacities[i])
        prev2 = prev1
        prev1 = curr
    return prev1

def min_token_denominations_for_amount(token_types, target_cost):
    dp = [float("inf")] * (target_cost + 1)
    dp[0] = 0
    for token in token_types:
        for amount in range(token, target_cost + 1):
            if dp[amount - token] + 1 < dp[amount]:
                dp[amount] = dp[amount - token] + 1
    return dp[target_cost] if dp[target_cost] != float("inf") else -1

import bisect

def length_of_strictly_ascending_run(signal_values):
    tails = []
    for x in signal_values:
        idx = bisect.bisect_left(tails, x)
        if idx == len(tails):
            tails.append(x)
        else:
            tails[idx] = x
    return len(tails)

def count_unique_grid_paths(grid_rows, grid_cols):
    dp = [1] * grid_cols
    for _ in range(1, grid_rows):
        for c in range(1, grid_cols):
            dp[c] += dp[c - 1]
    return dp[-1]

def longest_shared_subsequence_len(text_alpha, text_beta):
    m, n = len(text_alpha), len(text_beta)
    prev = [0] * (n + 1)
    for i in range(1, m + 1):
        curr = [0] * (n + 1)
        for j in range(1, n + 1):
            if text_alpha[i - 1] == text_beta[j - 1]:
                curr[j] = prev[j - 1] + 1
            else:
                curr[j] = max(prev[j], curr[j - 1])
        prev = curr
    return prev[n]

def max_knapsack_value(weights, values, max_capacity):
    dp = [0] * (max_capacity + 1)
    for w, v in zip(weights, values):
        for cap in range(max_capacity, w - 1, -1):
            if dp[cap - w] + v > dp[cap]:
                dp[cap] = dp[cap - w] + v
    return dp[max_capacity]

def min_edit_distance_operations(initial_str, target_str):
    m, n = len(initial_str), len(target_str)
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(m + 1):
        dp[i][0] = i
    for j in range(n + 1):
        dp[0][j] = j
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if initial_str[i - 1] == target_str[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]
            else:
                dp[i][j] = 1 + min(dp[i - 1][j], dp[i][j - 1], dp[i - 1][j - 1])
    return dp[m][n]

def can_partition_into_equal_subsets(nums):
    total = sum(nums)
    if total % 2 != 0:
        return False
    target = total // 2
    dp = [False] * (target + 1)
    dp[0] = True
    for num in nums:
        for j in range(target, num - 1, -1):
            dp[j] = dp[j] or dp[j - num]
    return dp[target]

def combination_sum_permutations(distinct_nums, target_val):
    dp = [0] * (target_val + 1)
    dp[0] = 1
    for target in range(1, target_val + 1):
        for num in distinct_nums:
            if target >= num:
                dp[target] += dp[target - num]
    return dp[target_val]

def max_profit_with_cooldown(stock_prices):
    if not stock_prices:
        return 0
    hold = -stock_prices[0]
    sold = 0
    rest = 0
    for price in stock_prices[1:]:
        prev_sold = sold
        sold = hold + price
        hold = max(hold, rest - price)
        rest = max(rest, prev_sold)
    return max(sold, rest)

def longest_palindromic_subseq_len(text_sequence):
    n = len(text_sequence)
    dp = [[0] * n for _ in range(n)]
    for i in range(n - 1, -1, -1):
        dp[i][i] = 1
        for j in range(i + 1, n):
            if text_sequence[i] == text_sequence[j]:
                dp[i][j] = dp[i + 1][j - 1] + 2
            else:
                dp[i][j] = max(dp[i + 1][j], dp[i][j - 1])
    return dp[0][n - 1]

def can_segment_into_dictionary_words(stream_str, word_dict):
    words_set = set(word_dict)
    n = len(stream_str)
    dp = [False] * (n + 1)
    dp[0] = True
    for i in range(1, n + 1):
        for j in range(i):
            if dp[j] and stream_str[j:i] in words_set:
                dp[i] = True
                break
    return dp[n]

def min_path_sum_in_grid(grid_weights):
    m, n = len(grid_weights), len(grid_weights[0])
    dp = [0] * n
    dp[0] = grid_weights[0][0]
    for j in range(1, n):
        dp[j] = dp[j - 1] + grid_weights[0][j]
    for i in range(1, m):
        dp[0] += grid_weights[i][0]
        for j in range(1, n):
            dp[j] = min(dp[j], dp[j - 1]) + grid_weights[i][j]
    return dp[-1]

