def num_cipher_decodings(cipher_digits):
    if not cipher_digits or cipher_digits[0] == "0":
        return 0
    prev2, prev1 = 1, 1
    for i in range(1, len(cipher_digits)):
        curr = 0
        one_digit = int(cipher_digits[i])
        two_digits = int(cipher_digits[i - 1:i + 1])
        if one_digit != 0:
            curr += prev1
        if 10 <= two_digits <= 26:
            curr += prev2
        prev2 = prev1
        prev1 = curr
    return prev1

def maximal_square_area(matrix_grid):
    if not matrix_grid:
        return 0
    m, n = len(matrix_grid), len(matrix_grid[0])
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    max_side = 0
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if matrix_grid[i - 1][j - 1] == "1":
                dp[i][j] = 1 + min(dp[i - 1][j], dp[i][j - 1], dp[i - 1][j - 1])
                if dp[i][j] > max_side:
                    max_side = dp[i][j]
    return max_side * max_side

def integer_break_max_product(n):
    if n <= 3:
        return n - 1
    dp = [0] * (n + 1)
    dp[1], dp[2], dp[3] = 1, 2, 3
    for i in range(4, n + 1):
        dp[i] = max(2 * dp[i - 2], 3 * dp[i - 3])
    return dp[n]

def longest_subsequence_with_diff(arr, difference):
    dp = {}
    max_len = 0
    for x in arr:
        dp[x] = dp.get(x - difference, 0) + 1
        if dp[x] > max_len:
            max_len = dp[x]
    return max_len

