def shortest_path_visiting_all_nodes_cost(graph_adj):
    n = len(graph_adj)
    if n == 1:
        return 0
    final_state = (1 << n) - 1
    queue = deque()
    visited = set()
    for node in range(n):
        mask = 1 << node
        queue.append((node, mask, 0))
        visited.add((node, mask))
    while queue:
        curr, mask, dist = queue.popleft()
        if mask == final_state:
            return dist
        for neighbor in graph_adj[curr]:
            next_mask = mask | (1 << neighbor)
            if (neighbor, next_mask) not in visited:
                visited.add((neighbor, next_mask))
                queue.append((neighbor, next_mask, dist + 1))
    return -1

