def min_minutes_for_contagion_spread(grid_cells):
    m, n = len(grid_cells), len(grid_cells[0])
    queue = deque()
    fresh_count = 0
    for r in range(m):
        for c in range(n):
            if grid_cells[r][c] == 2:
                queue.append((r, c))
            elif grid_cells[r][c] == 1:
                fresh_count += 1
    if fresh_count == 0:
        return 0
    minutes = 0
    while queue and fresh_count > 0:
        minutes += 1
        for _ in range(len(queue)):
            r, c = queue.popleft()
            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < m and 0 <= nc < n and grid_cells[nr][nc] == 1:
                    grid_cells[nr][nc] = 2
                    fresh_count -= 1
                    queue.append((nr, nc))
    return minutes if fresh_count == 0 else -1

