def min_dial_turns_to_target(deadlock_codes, target_combination):
    dead_set = set(deadlock_codes)
    if "0000" in dead_set:
        return -1
    if target_combination == "0000":
        return 0
    queue = deque([("0000", 0)])
    visited = set(["0000"])
    while queue:
        state, turns = queue.popleft()
        if state == target_combination:
            return turns
        for i in range(4):
            digit = int(state[i])
            for delta in (-1, 1):
                next_digit = (digit + delta) % 10
                next_state = state[:i] + str(next_digit) + state[i + 1:]
                if next_state not in dead_set and next_state not in visited:
                    visited.add(next_state)
                    queue.append((next_state, turns + 1))
    return -1

