def is_bipartite_graph(graph_adj):
    n = len(graph_adj)
    colors = {}
    for node in range(n):
        if node not in colors:
            colors[node] = 0
            queue = deque([node])
            while queue:
                curr = queue.popleft()
                curr_color = colors[curr]
                for neighbor in graph_adj[curr]:
                    if neighbor not in colors:
                        colors[neighbor] = 1 - curr_color
                        queue.append(neighbor)
                    elif colors[neighbor] == curr_color:
                        return False
    return True

