def pacific_atlantic_flow_coordinates(heights):
    if not heights:
        return []
    m, n = len(heights), len(heights[0])
    pacific_q = deque()
    atlantic_q = deque()
    pacific_visited = set()
    atlantic_visited = set()
    for r in range(m):
        pacific_q.append((r, 0))
        pacific_visited.add((r, 0))
        atlantic_q.append((r, n - 1))
        atlantic_visited.add((r, n - 1))
    for c in range(n):
        pacific_q.append((0, c))
        pacific_visited.add((0, c))
        atlantic_q.append((m - 1, c))
        atlantic_visited.add((m - 1, c))
    def bfs(q, visited):
        while q:
            r, c = q.popleft()
            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < m and 0 <= nc < n and (nr, nc) not in visited:
                    if heights[nr][nc] >= heights[r][c]:
                        visited.add((nr, nc))
                        q.append((nr, nc))
    bfs(pacific_q, pacific_visited)
    bfs(atlantic_q, atlantic_visited)
    return sorted(list(pacific_visited & atlantic_visited))

