def min_snakes_and_ladders_moves(board_grid):
    n = len(board_grid)
    def get_coords(square):
        row = (square - 1) // n
        col = (square - 1) % n
        if row % 2 == 1:
            col = n - 1 - col
        return n - 1 - row, col
    queue = deque([(1, 0)])
    visited = set([1])
    while queue:
        curr, rolls = queue.popleft()
        if curr == n * n:
            return rolls
        for dice in range(1, 7):
            next_sq = curr + dice
            if next_sq <= n * n:
                r, c = get_coords(next_sq)
                destination = board_grid[r][c] if board_grid[r][c] != -1 else next_sq
                if destination not in visited:
                    visited.add(destination)
                    queue.append((destination, rolls + 1))
    return -1

