def find_all_shortest_ladders(begin_word, end_word, word_list):
    words = set(word_list)
    if end_word not in words:
        return []
    parents = defaultdict(set)
    level = {begin_word}
    found = False
    while level and not found:
        words -= level
        next_level = set()
        for word in level:
            for i in range(len(word)):
                for ch in "abcdefghijklmnopqrstuvwxyz":
                    nxt = word[:i] + ch + word[i + 1:]
                    if nxt in words:
                        if nxt == end_word:
                            found = True
                        next_level.add(nxt)
                        parents[nxt].add(word)
        level = next_level
    results = []
    def backtrack(curr, path):
        if curr == begin_word:
            results.append(path[::-1])
            return
        for p in parents[curr]:
            backtrack(p, path + [p])
    if found:
        backtrack(end_word, [end_word])
    return results

def min_jumps_to_reach_end(jump_capacities):
    n = len(jump_capacities)
    if n <= 1:
        return 0
    jumps = 0
    curr_end = 0
    farthest = 0
    for i in range(n - 1):
        if i + jump_capacities[i] > farthest:
            farthest = i + jump_capacities[i]
        if i == curr_end:
            jumps += 1
            curr_end = farthest
            if curr_end >= n - 1:
                break
    return jumps

