def min_obstacles_eliminated_to_target(grid_terrain, max_eliminations):
    m, n = len(grid_terrain), len(grid_terrain[0])
    if max_eliminations >= m + n - 2:
        return m + n - 2
    queue = deque([(0, 0, max_eliminations, 0)])
    visited = {(0, 0): max_eliminations}
    while queue:
        r, c, k, steps = queue.popleft()
        if r == m - 1 and c == n - 1:
            return steps
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < m and 0 <= nc < n:
                next_k = k - grid_terrain[nr][nc]
                if next_k >= 0 and next_k > visited.get((nr, nc), -1):
                    visited[(nr, nc)] = next_k
                    queue.append((nr, nc, next_k, steps + 1))
    return -1

from collections import deque

def width_of_binary_tree_max(root):
    if not root:
        return 0
    max_width = 0
    queue = deque([(root, 0)])
    while queue:
        level_len = len(queue)
        _, first_col = queue[0]
        col_idx = first_col
        for _ in range(level_len):
            node, col_idx = queue.popleft()
            norm_col = col_idx - first_col
            if node.left:
                queue.append((node.left, 2 * norm_col))
            if node.right:
                queue.append((node.right, 2 * norm_col + 1))
        width = col_idx - first_col + 1
        if width > max_width:
            max_width = width
    return max_width

from collections import deque, defaultdict

def count_reachable_nodes_restricted(n, edges, restricted):
    restricted_set = set(restricted)
    adj = defaultdict(list)
    for u, v in edges:
        if u not in restricted_set and v not in restricted_set:
            adj[u].append(v)
            adj[v].append(u)
    visited = {0}
    queue = deque([0])
    count = 0
    while queue:
        curr = queue.popleft()
        count += 1
        for neighbor in adj[curr]:
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append(neighbor)
    return count
